BEGIN;
CREATE TABLE public.academic_periods(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,school_id uuid NOT NULL,code text NOT NULL,starts_on date NOT NULL,ends_on date NOT NULL,status text NOT NULL CHECK(status IN ('draft','active','closed')),FOREIGN KEY(tenant_id,school_id) REFERENCES public.schools(tenant_id,id),UNIQUE(tenant_id,school_id,id),UNIQUE(tenant_id,school_id,code),CHECK(ends_on>=starts_on));
CREATE TABLE public.subjects(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,school_id uuid NOT NULL,code text NOT NULL,name text NOT NULL,FOREIGN KEY(tenant_id,school_id) REFERENCES public.schools(tenant_id,id),UNIQUE(tenant_id,school_id,id),UNIQUE(tenant_id,school_id,code));
CREATE TABLE public.assessments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,school_id uuid NOT NULL,class_id uuid NOT NULL,subject_id uuid NOT NULL,period_id uuid NOT NULL,title text NOT NULL,max_score numeric(8,2) NOT NULL CHECK(max_score>0),status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','submitted','approved','published')),published_at timestamptz,created_by uuid NOT NULL REFERENCES public.users(id),FOREIGN KEY(tenant_id,school_id,class_id) REFERENCES public.school_classes(tenant_id,school_id,id),FOREIGN KEY(tenant_id,school_id,subject_id) REFERENCES public.subjects(tenant_id,school_id,id),FOREIGN KEY(tenant_id,school_id,period_id) REFERENCES public.academic_periods(tenant_id,school_id,id),UNIQUE(tenant_id,school_id,id),CHECK((status='published' AND published_at IS NOT NULL) OR (status<>'published' AND published_at IS NULL)));
CREATE TABLE public.student_grades(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,school_id uuid NOT NULL,assessment_id uuid NOT NULL,student_id uuid NOT NULL,score numeric(8,2),status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','submitted','approved','published')),published_at timestamptz,revision integer NOT NULL DEFAULT 1 CHECK(revision>0),updated_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(tenant_id,school_id,assessment_id) REFERENCES public.assessments(tenant_id,school_id,id),FOREIGN KEY(tenant_id,school_id,student_id) REFERENCES public.students(tenant_id,school_id,id),UNIQUE(tenant_id,school_id,assessment_id,student_id),CHECK(score IS NULL OR score>=0),CHECK((status='published' AND published_at IS NOT NULL) OR (status<>'published' AND published_at IS NULL)));
CREATE TABLE public.attendance_sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,school_id uuid NOT NULL,class_id uuid NOT NULL,period_id uuid NOT NULL,session_date date NOT NULL,state text NOT NULL DEFAULT 'draft' CHECK(state IN ('draft','confirmed','published')),published_at timestamptz,FOREIGN KEY(tenant_id,school_id,class_id) REFERENCES public.school_classes(tenant_id,school_id,id),FOREIGN KEY(tenant_id,school_id,period_id) REFERENCES public.academic_periods(tenant_id,school_id,id),UNIQUE(tenant_id,school_id,id),UNIQUE(tenant_id,school_id,class_id,session_date),CHECK((state='published' AND published_at IS NOT NULL) OR (state<>'published' AND published_at IS NULL)));
CREATE TABLE public.attendance_records(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,school_id uuid NOT NULL,session_id uuid NOT NULL,student_id uuid NOT NULL,attendance_code text NOT NULL CHECK(attendance_code IN ('present','sick','excused','absent','late')),internal_note text,FOREIGN KEY(tenant_id,school_id,session_id) REFERENCES public.attendance_sessions(tenant_id,school_id,id),FOREIGN KEY(tenant_id,school_id,student_id) REFERENCES public.students(tenant_id,school_id,id),UNIQUE(tenant_id,school_id,session_id,student_id));
CREATE TABLE public.report_cards(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,school_id uuid NOT NULL,student_id uuid NOT NULL,period_id uuid NOT NULL,version integer NOT NULL CHECK(version>0),state text NOT NULL DEFAULT 'draft' CHECK(state IN ('draft','review','approved','published','superseded')),published_at timestamptz,payload jsonb NOT NULL DEFAULT '{}'::jsonb,FOREIGN KEY(tenant_id,school_id,student_id) REFERENCES public.students(tenant_id,school_id,id),FOREIGN KEY(tenant_id,school_id,period_id) REFERENCES public.academic_periods(tenant_id,school_id,id),UNIQUE(tenant_id,school_id,id),UNIQUE(tenant_id,school_id,student_id,period_id,version),CHECK((state='published' AND published_at IS NOT NULL) OR (state<>'published' AND published_at IS NULL)));
CREATE TABLE public.ews_rules(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,school_id uuid NOT NULL,rule_key text NOT NULL,version integer NOT NULL CHECK(version>0),state text NOT NULL DEFAULT 'draft' CHECK(state IN ('draft','active','retired')),parameters jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(tenant_id,school_id) REFERENCES public.schools(tenant_id,id),UNIQUE(tenant_id,school_id,id),UNIQUE(tenant_id,school_id,rule_key,version));
CREATE TABLE public.ews_alerts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,school_id uuid NOT NULL,student_id uuid NOT NULL,rule_id uuid NOT NULL,window_key text NOT NULL,status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','under_review','resolved','dismissed')),severity text NOT NULL CHECK(severity IN ('monitor','review')),explanation text NOT NULL,detected_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(tenant_id,school_id,student_id) REFERENCES public.students(tenant_id,school_id,id),FOREIGN KEY(tenant_id,school_id,rule_id) REFERENCES public.ews_rules(tenant_id,school_id,id),UNIQUE(tenant_id,school_id,id),UNIQUE(tenant_id,school_id,student_id,rule_id,window_key));
CREATE TABLE public.ews_case_notes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,school_id uuid NOT NULL,alert_id uuid NOT NULL,author_user_id uuid NOT NULL REFERENCES public.users(id),note text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(tenant_id,school_id,alert_id) REFERENCES public.ews_alerts(tenant_id,school_id,id));
DO $$DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['academic_periods','subjects','assessments','student_grades','attendance_sessions','attendance_records','report_cards','ews_rules','ews_alerts','ews_case_notes'] LOOP EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('ALTER TABLE public.%I FORCE ROW LEVEL SECURITY',t);END LOOP;END$$;
CREATE OR REPLACE FUNCTION app.g03d_teacher_student(p_tenant uuid,p_school uuid,p_student uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,app AS $$ SELECT app.has_active_membership(p_tenant,p_school,ARRAY['teacher']) AND EXISTS(SELECT 1 FROM public.teacher_class_assignments t JOIN public.class_student_enrollments e ON e.tenant_id=t.tenant_id AND e.school_id=t.school_id AND e.class_id=t.class_id WHERE t.tenant_id=p_tenant AND t.school_id=p_school AND t.teacher_user_id=app.current_user_id() AND t.status='active' AND e.student_id=p_student AND e.status='active') $$;
CREATE OR REPLACE FUNCTION app.g03d_guardian_student(p_tenant uuid,p_school uuid,p_student uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,app AS $$ SELECT app.has_active_membership(p_tenant,p_school,ARRAY['guardian']) AND EXISTS(SELECT 1 FROM public.guardian_student_links l WHERE l.tenant_id=p_tenant AND l.school_id=p_school AND l.student_id=p_student AND l.guardian_user_id=app.current_user_id() AND l.verification_status='verified') $$;
CREATE OR REPLACE FUNCTION app.g03d_grant(p_tenant uuid,p_school uuid,p_student uuid,p_resource text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,app AS $$ SELECT app.has_active_membership(p_tenant,NULL,ARRAY['foundation_admin','foundation_analyst']) AND EXISTS(SELECT 1 FROM public.access_grants g JOIN public.access_requests r ON r.id=g.request_id WHERE g.tenant_id=p_tenant AND g.school_id=p_school AND g.student_id=p_student AND g.grantee_user_id=app.current_user_id() AND p_resource=ANY(g.resource_types) AND g.revoked_at IS NULL AND statement_timestamp()>=g.starts_at AND statement_timestamp()<g.expires_at AND r.status='approved' AND r.conflict_flag=false AND g.approved_by<>g.grantee_user_id AND EXISTS(SELECT 1 FROM public.memberships m WHERE m.user_id=g.approved_by AND m.tenant_id=p_tenant AND m.school_id=p_school AND m.role_code='principal' AND m.status='active') AND NOT EXISTS(SELECT 1 FROM public.approval_escalations e WHERE e.request_id=g.request_id)) $$;
CREATE OR REPLACE FUNCTION app.g03d_can_read(p_tenant uuid,p_school uuid,p_student uuid,p_resource text,p_published boolean) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,app AS $$ SELECT app.current_user_id() IS NOT NULL AND EXISTS(SELECT 1 FROM public.students s WHERE s.tenant_id=p_tenant AND s.school_id=p_school AND s.id=p_student) AND CASE WHEN p_resource='ews_alert' THEN app.has_active_membership(p_tenant,p_school,ARRAY['principal']) OR app.g03d_teacher_student(p_tenant,p_school,p_student) WHEN p_resource IN ('grade','attendance','report_card') THEN app.has_active_membership(p_tenant,p_school,ARRAY['principal']) OR app.g03d_teacher_student(p_tenant,p_school,p_student) OR (p_published AND app.g03d_guardian_student(p_tenant,p_school,p_student)) OR (app.g03d_grant(p_tenant,p_school,p_student,p_resource) AND (p_resource<>'report_card' OR p_published)) ELSE false END $$;
CREATE POLICY g03d_grade_read ON public.student_grades FOR SELECT USING(app.g03d_can_read(tenant_id,school_id,student_id,'grade',status='published' AND published_at IS NOT NULL));
CREATE POLICY g03d_attendance_read ON public.attendance_records FOR SELECT USING(app.g03d_can_read(tenant_id,school_id,student_id,'attendance',EXISTS(SELECT 1 FROM public.attendance_sessions x WHERE x.tenant_id=attendance_records.tenant_id AND x.school_id=attendance_records.school_id AND x.id=attendance_records.session_id AND x.state='published' AND x.published_at IS NOT NULL)));
CREATE POLICY g03d_report_read ON public.report_cards FOR SELECT USING(app.g03d_can_read(tenant_id,school_id,student_id,'report_card',state='published' AND published_at IS NOT NULL));
CREATE POLICY g03d_ews_alert_read ON public.ews_alerts FOR SELECT USING(app.g03d_can_read(tenant_id,school_id,student_id,'ews_alert',false));
REVOKE ALL ON FUNCTION app.g03d_teacher_student(uuid,uuid,uuid),app.g03d_guardian_student(uuid,uuid,uuid),app.g03d_grant(uuid,uuid,uuid,text),app.g03d_can_read(uuid,uuid,uuid,text,boolean) FROM PUBLIC;
COMMIT;
